import{_ as i,l as o,o as a,c as r,v as t,p,x as l,d,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const U=JSON.parse('{"title":"CPU 推理与量化","description":"","frontmatter":{"title":"CPU 推理与量化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cpu-inference-quant.md","filePath":"llm/cpu-inference-quant.md","lastUpdated":1789023840000}'),m={name:"llm/cpu-inference-quant.md"};function u(h,e,P,_,A,f){const n=o("Mermaid");return a(),r("div",null,[e[1]||(e[1]=t('<h1 id="cpu-推理与量化" tabindex="-1">CPU 推理与量化 <a class="header-anchor" href="#cpu-推理与量化" aria-label="Permalink to &quot;CPU 推理与量化&quot;">​</a></h1><div class="epigraph"><p>没有 Tensor Core 时，4-bit 权重要变成 SIMD 或 AMX 能吃的块：量化是数据类型，也是内核布局。</p><footer>—— ggml / llama.cpp 的 k-quant；至强 AMX 见 Intel 手册；8-bit 训练侧对照 Dettmers 等，推理侧以 ggml 与 bitsandbytes 为常见路径</footer></div><p><a href="/llm/mobile-npu-deploy">上一课</a>把循环留给 CPU 也是常见结局。本课把 CPU 当一等推理器：<a href="/llm/llamacpp">llama.cpp</a> + <a href="/llm/gguf">GGUF</a> 在 AVX/NEON/AMX/Metal 上跑量化 matmul；数据中心至强用 AMX 吃 INT8/BF16。会计：DDR 带宽更低，\\(B=1\\) 更彻底绑在读权重上，量化的导数最大。不要把 GPU FP8 核的速度抄过来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FP16 7B 放不进 16GB 还要给 OS 留余量。必须权重量化，且 <em>核直接吃量化块</em>，不能先反量化成 FP16 再通用 GEMM——那会把带宽账单涨回去。缺口是布局：k-quant 超级块、AMX 的 tile 形状、AVX 的 32 元组，必须与文件里的块一致。<a href="/llm/kernel-autotuning">内核自动调优</a>在 CPU 上是选 kernel 变体与线程绑核，不是 Triton tile。</p><p>线程：decode \\(B=1\\) 时多线程切隐藏维或层内 GEMM；过多线程会在共享 L3 上互抢。NUMA 绑定错误比少用两个核更伤。OpenMP / ggml 的 <code>n_threads</code> 应钉在物理核，并把进程绑到同一 socket，否则量化块的尺度与权重被拆到远端内存，逐步抖动会看起来像「量化质量差」。</p><p><span class="marginnote">KV 仍建议量化或短 \\(n\\)。只量化权重、KV 留 FP16，长上下文在笔记本上照样 OOM。公式与 GPU 课相同，换 \\(b\\) 与容量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本地：选 GGUF 类型（<code>Q4_K_M</code> 等），mmap，线程数 ≈ 物理核或略少。服务器 CPU：AMX INT8 路径要 palettize tile，见 AMX 课；MoE 专家批在 CPU 上更难凑，宁可稠密小模型。与 GPU 混合：CPU 做分词与小草稿，GPU 做目标——下一课端云、再下一课端侧投机。采样在 CPU 上词表扫描相对可接受，因为逐步已被 DDR 主导。</p>',9)),(a(),p(c,null,{default:l(()=>[s(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GGUF%5B%22GGUF%20%E9%87%8F%E5%8C%96%E5%9D%97%20mmap%22%5D%20--%3E%20K%5B%22SIMD%2FAMX%20%E5%8F%8D%E9%87%8F%E5%8C%96%E7%82%B9%E7%A7%AF%22%5D%0A%20%20K%20--%3E%20TOK%5B%22%E4%B8%80%E6%AD%A5%20token%22%5D%0A%20%20THR%5B%22%E7%BA%BF%E7%A8%8B%E7%BB%91%E6%A0%B8%20%2F%20NUMA%22%5D%20--%3E%20K%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(I\\) 更低，量化减字节几乎线性减步时（直到核常数或 L3 打满）。AMX 提高算术吞吐，把工作点略往算力推，但 \\(B=1\\) 的 decode 仍难离开带宽屋顶。这解释了为什么 CPU 上 4-bit 相对 8-bit 的加速比往往比 GPU 上更「值」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 Python 循环 decode。不要在超线程上加倍线程当免费 2×。质量：k-quant 与 GPTQ 不是同一误差，基准要锁类型。下一课：端与云如何切，而不是二选一。</p><p>出处：llama.cpp / GGUF；Intel AMX；Dettmers 等 8-bit 工作为相关背景。不发明编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPU decode 更深地绑在读量化权重；核必须直接吃分块量化。</li><li>线程与 NUMA 是一阶；超线程不是 2×。</li><li>KV 与 \\(n\\) 仍按容量公式。</li><li>AMX 改善常数，不自动变成 compute-bound。</li><li>码本与 GPU 量化不可混比。</li><li>下一课：端云协同。</li><li>出处：llama.cpp；Intel AMX。</li></ul>',7))])}const E=i(m,[["render",u]]);export{U as __pageData,E as default};
